#![allow(dead_code)]
#[path="/tmp/eris-before-js_string.rs"] mod js_string;
#[path="/tmp/eris-matching-old-regexp.rs"] mod old;
#[path="/home/eriskii/Documents/Programming/Projects/ErisBrowser/src/regexp.rs"] mod new;
use js_string::JsString;
fn ob()->old::Budget{old::Budget{steps:100_000,allocated:0,heap_limit:8*1024*1024,stack_limit:22}}
fn nb()->new::Budget{new::Budget{steps:100_000,allocated:0,heap_limit:8*1024*1024,stack_limit:22}}
fn main(){
 let atoms=["a","b",".","[ab]","[^a]","[\\d]","[\\s]","[^]","[]","()","(a)","(?:a|)","(a|ab)","(a(b)?)","(?=a)","(?!b)","(?<x>a)","(a)\\1","(a)?\\1","\\b","^","$","\\uD800","{x}"];
 let suffixes=["","?","*","+","??","*?","{0}","{2,3}","{2,1}"];
 let tails=["","b","|a","|","(a)?","$","(?!b)","\\k<x>",")"];
 let inputs=["","a","b","ab","aa","aba","aab","abba","\na","A","😀"];
 let mut parses=0;let mut matches=0;
 for atom in atoms{for suffix in suffixes{for tail in tails{for flags in ["","im"]{
  let source=format!("{atom}{suffix}{tail}");
  let a=old::RegExp::compile(source.clone().into(),&flags.into(),&mut ob());
  let b=new::RegExp::compile(source.clone().into(),&flags.into(),&mut nb());parses+=1;
  match(a,b){
   (Ok(a),Ok(b))=>for input in inputs{let text=JsString::from(input);for sticky in [false,true]{for start in [0,1]{
    let x=a.find(text.units(),start,sticky,&mut ob()).map(|x|x.map(|m|m.captures));
    let y=b.find(text.units(),start,sticky,&mut nb()).map(|x|x.map(|m|m.captures));
    assert_eq!(format!("{x:?}"),format!("{y:?}"),"/{source}/{flags} input={input:?} start={start} sticky={sticky}");matches+=1;
   }}},
   (Err(a),Err(b))=>assert_eq!(format!("{a:?}"),format!("{b:?}"),"/{source}/{flags}"),
   (a,b)=>panic!("compile difference /{source}/{flags}: {a:?} {b:?}")
  }
 }}}}
 println!("PASS: {parses} identical parse outcomes; {matches} identical full capture/error outcomes (two flags, two start indices, sticky and scanning)");
}

