use js_string::JsString;
use std::{hint::black_box,time::Instant};
macro_rules! benchmark {($name:ident,$module:ident)=>{
fn $name(source:&str,text:&str,iterations:usize,compile_only:bool)->(u128,usize,usize,usize) {
 let make=||$module::Budget{steps:100_000,allocated:0,heap_limit:8*1024*1024,stack_limit:22};
 let pattern=JsString::from(source);let flags=JsString::from("");let text=JsString::from(text);
 let compiled=$module::RegExp::compile(pattern.clone(),&flags,&mut make()).unwrap();
 let started=Instant::now();let mut pass=0;let mut miss=0;let mut error=0;
 for _ in 0..iterations {
  let mut b=make();
  if compile_only {black_box($module::RegExp::compile(pattern.clone(),&flags,&mut b).unwrap());pass+=1;}
  else {match black_box(compiled.find(text.units(),0,false,&mut b)){Ok(Some(_))=>pass+=1,Ok(None)=>miss+=1,Err(_)=>error+=1}}
 }
 (started.elapsed().as_nanos(),pass,miss,error)
}}}
benchmark!(old_run,old);benchmark!(new_run,new);
fn main(){
 let cases=[
 ("literal-match","hello".to_string(),"hello".to_string(),10000,false),
 ("literal-compile","hello".to_string(),"".to_string(),10000,true),
 ("repeat-compile","a+b".to_string(),"".to_string(),10000,true),
 ("repeat-short-match","a+b".to_string(),"aaab".to_string(),10000,false),
 ("repeat-early-match","a+b".to_string(),format!("ab{}","x".repeat(512)),10000,false),
 ("repeat-long-match","a+b".to_string(),format!("{}b","a".repeat(512)),500,false),
 ("prefix-missing","z+".to_string(),"a".repeat(512),1000,false),
 ("class-repeat","[ab]+".to_string(),"a".repeat(512),500,false),
 ("delimiter-missing","[^?]*\\?+".to_string(),"a".repeat(512),200,false),
 ("xml-compile",std::fs::read_to_string("/tmp/eris-regexp-xml-inputs/23.txt").unwrap(),"".to_string(),1000,true),
 ];
 for (name,source,text,n,compile) in cases {
  old_run(&source,&text,16,compile);new_run(&source,&text,16,compile);
  for sample in 0..7 {
   let (a,b)=if sample%2==0{let a=old_run(&source,&text,n,compile);let b=new_run(&source,&text,n,compile);(a,b)}else{let b=new_run(&source,&text,n,compile);let a=old_run(&source,&text,n,compile);(a,b)};
   println!("{name}\t{sample}\t{n}\t{}\t{}\t{:?}\t{:?}",a.0,b.0,(a.1,a.2,a.3),(b.1,b.2,b.3));
  }
 }
}
